import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"15、【谦】 艮下坤上","description":"温公易说 - 15、【谦】 艮下坤上","frontmatter":{"title":"15、【谦】 艮下坤上","description":"温公易说 - 15、【谦】 艮下坤上"},"headers":[],"relativePath":"zh/classics/wengong/016.md","filePath":"zh/classics/wengong/016.md"}'),n={name:"zh/classics/wengong/016.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_15、【谦】-艮下坤上" tabindex="-1">15、【谦】 艮下坤上 <a class="header-anchor" href="#_15、【谦】-艮下坤上" aria-label="Permalink to “15、【谦】 艮下坤上”">​</a></h1><h3 id="彖曰-谦-亨。天道下济而光明-地道卑而上行。天道亏盈而益谦-地道变盈而流谦。鬼神害盈而福谦-人道恶盈而好谦。谦尊而光-卑而不可逾。君子之终也。" tabindex="-1">彖曰：谦，亨。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦。鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾。君子之终也。 <a class="header-anchor" href="#彖曰-谦-亨。天道下济而光明-地道卑而上行。天道亏盈而益谦-地道变盈而流谦。鬼神害盈而福谦-人道恶盈而好谦。谦尊而光-卑而不可逾。君子之终也。" aria-label="Permalink to “彖曰：谦，亨。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦。鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾。君子之终也。”">​</a></h3><p>人之将有行也，将有为也。施之以谦，则无不通也。君子之德，诚盛矣，业诚大矣。不谦以持之，则无以保其终也。故夫谦者，君子之终也。</p><h3 id="象曰-地中有山-谦。君子以裒多益寡-称物平施。" tabindex="-1">象曰：地中有山，谦。君子以裒多益寡，称物平施。 <a class="header-anchor" href="#象曰-地中有山-谦。君子以裒多益寡-称物平施。" aria-label="Permalink to “象曰：地中有山，谦。君子以裒多益寡，称物平施。”">​</a></h3><h3 id="初六-谦谦-君子用涉大川-吉-象曰-谦谦君子-卑以自牧也。" tabindex="-1">初六：谦谦，君子用涉大川，吉 象曰：谦谦君子，卑以自牧也。 <a class="header-anchor" href="#初六-谦谦-君子用涉大川-吉-象曰-谦谦君子-卑以自牧也。" aria-label="Permalink to “初六：谦谦，君子用涉大川，吉 象曰：谦谦君子，卑以自牧也。”">​</a></h3><h3 id="六二-鸣谦-贞吉-象曰-鸣谦贞吉-中心得也。" tabindex="-1">六二：鸣谦，贞吉 象曰：鸣谦贞吉，中心得也。 <a class="header-anchor" href="#六二-鸣谦-贞吉-象曰-鸣谦贞吉-中心得也。" aria-label="Permalink to “六二：鸣谦，贞吉 象曰：鸣谦贞吉，中心得也。”">​</a></h3><h3 id="九三-劳谦-君子有终-吉-象曰-劳谦君子-万民服也。" tabindex="-1">九三：劳谦，君子有终，吉 象曰：劳谦君子，万民服也。 <a class="header-anchor" href="#九三-劳谦-君子有终-吉-象曰-劳谦君子-万民服也。" aria-label="Permalink to “九三：劳谦，君子有终，吉 象曰：劳谦君子，万民服也。”">​</a></h3><p>劳谦，有劳而谦者也。</p><h3 id="六四-无不利-撝谦-象曰-无不利撝谦-不违则也。" tabindex="-1">六四：无不利，撝谦 象曰：无不利撝谦，不违则也。 <a class="header-anchor" href="#六四-无不利-撝谦-象曰-无不利撝谦-不违则也。" aria-label="Permalink to “六四：无不利，撝谦 象曰：无不利撝谦，不违则也。”">​</a></h3><h3 id="六五-不富以其邻-利用侵伐-无不利-象曰-利用侵伐-征不服也。" tabindex="-1">六五：不富以其邻，利用侵伐，无不利 象曰：利用侵伐，征不服也。 <a class="header-anchor" href="#六五-不富以其邻-利用侵伐-无不利-象曰-利用侵伐-征不服也。" aria-label="Permalink to “六五：不富以其邻，利用侵伐，无不利 象曰：利用侵伐，征不服也。”">​</a></h3><h3 id="上六-鸣谦-利用行师-征邑国-象曰-鸣谦-志未得也。可用行师-征邑国也。" tabindex="-1">上六：鸣谦，利用行师，征邑国 象曰：鸣谦，志未得也。可用行师，征邑国也。 <a class="header-anchor" href="#上六-鸣谦-利用行师-征邑国-象曰-鸣谦-志未得也。可用行师-征邑国也。" aria-label="Permalink to “上六：鸣谦，利用行师，征邑国 象曰：鸣谦，志未得也。可用行师，征邑国也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
